// EDCqlLexerInit initializes any static state used to implement EDCqlLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewEDCqlLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func EDCqlLexerInit() {
	staticData := &EDCqlLexerLexerStaticData
	staticData.once.Do(edcqllexerLexerInit)
}

// NewEDCqlLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewEDCqlLexer(input antlr.CharStream) *EDCqlLexer {
	EDCqlLexerInit()
	l := new(EDCqlLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &EDCqlLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "EDCqlLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

